<?php require __DIR__.'/includes/bootstrap.php';require_login();if(user()['role']==='admin')redirect('/admin/index.php');if(user()['role']==='agent')redirect('/agent/index.php');$u=user();$h=$pdo->prepare('SELECT b.*,h.nom label,b.date_arrivee date1,b.date_depart date2 FROM room_bookings b JOIN rooms r ON b.room_id=r.id JOIN hotels h ON r.hotel_id=h.id WHERE b.user_id=? ORDER BY b.created_at DESC');$h->execute([$u['id']]);$hotels=$h->fetchAll();$t=$pdo->prepare('SELECT b.*,CONCAT(r.origine,\' → \' ,r.destination) label,s.date_depart date1 FROM ticket_bookings b JOIN trips_schedule s ON b.schedule_id=s.id JOIN routes r ON s.route_id=r.id WHERE b.user_id=? ORDER BY b.created_at DESC');$t->execute([$u['id']]);$tickets=$t->fetchAll();$p=$pdo->prepare('SELECT b.*,p.titre label,b.date_depart_choisie date1 FROM package_bookings b JOIN packages p ON p.id=b.package_id WHERE b.user_id=? ORDER BY b.created_at DESC');$p->execute([$u['id']]);$packages=$p->fetchAll();$all=array_merge($hotels,$tickets,$packages);usort($all,fn($a,$b)=>strtotime($b['created_at'])<=>strtotime($a['created_at']));$title='Mes voyages';require __DIR__.'/includes/header.php';?>
<section class="max-w-7xl mx-auto px-4 pb-12"><div class="page-heading"><p class="page-eyebrow">Espace voyageur</p><h1 class="page-title">Bonjour <?=e($u['nom'])?></h1><p class="page-subtitle">Retrouvez vos réservations et préparez la suite.</p></div><?php if(isset($_GET['success'])):?><div class="p-4 bg-emerald-50 border border-emerald-200 text-emerald-800 rounded-xl mt-4" role="status"><strong>Paiement simulé confirmé.</strong> Votre réservation est enregistrée.</div><?php endif;?>
<div class="grid sm:grid-cols-3 gap-4 mt-6"><article class="dashboard-stat"><span>Réservations</span><strong><?=count($all)?></strong></article><article class="dashboard-stat"><span>Hébergements</span><strong><?=count($hotels)?></strong></article><article class="dashboard-stat"><span>Billets & circuits</span><strong><?=count($tickets)+count($packages)?></strong></article></div>
<div class="flex justify-between items-end gap-3 mt-10"><div><p class="page-eyebrow">Votre activité</p><h2 class="text-2xl font-black mt-1">Mes réservations</h2></div><a href="/" class="text-teal-800 font-bold">Planifier un voyage →</a></div><div class="grid gap-3 mt-5"><?php foreach($all as $b):?><article class="booking-row"><div><div class="flex items-center gap-2"><span class="pill"><?=!empty($b['date2'])?'Hébergement':(isset($b['code_billet'])?'Billet':'Circuit')?></span><span class="text-xs text-slate-500">Référence #<?=$b['id']?></span></div><h3 class="font-extrabold text-lg mt-2"><?=e($b['label'])?></h3><p class="text-sm text-slate-600 mt-1">Départ / arrivée : <?=date('d/m/Y',strtotime($b['date1']))?><?php if(!empty($b['date2'])):?> — <?=date('d/m/Y',strtotime($b['date2']))?><?php endif;?></p><?php if(!empty($b['code_billet'])):?><p class="text-xs text-slate-500 mt-1">Code billet : <?=e($b['code_billet'])?></p><?php endif;?></div><div class="text-right"><strong><?=money($b['prix_total'])?></strong><p class="mt-2"><span class="status-pill"><?=e(str_replace('_',' ',$b['statut']))?></span></p></div></article><?php endforeach;?><?php if(!$all):?><div class="empty-state"><span class="text-3xl">✈</span><h3 class="text-slate-800 font-black mt-3">Votre prochain voyage commence ici.</h3><p class="mt-2">Recherchez un hébergement, un billet ou un circuit.</p><div class="flex justify-center flex-wrap gap-2 mt-4"><a class="btn" href="/hotels.php">Trouver un hôtel</a><a class="btn" href="/billets.php">Voir les billets</a></div></div><?php endif;?></div></section><?php require __DIR__.'/includes/footer.php';?>
